const GLOSSARY = [
  {t:"Aileron",say:"AY-luh-ron",d:"Hinged surfaces on the outer wing that roll the aircraft left or right — one goes up as the other goes down."},
  {t:"Airfoil",say:"AIR-foyl",d:"The cross-sectional shape of a wing, curved to deflect air downward and generate lift."},
  {t:"Altimeter",say:"al-TIM-uh-ter",d:"Instrument showing altitude, measured from air pressure and set against a local pressure reference."},
  {t:"Angle of attack",say:"—",d:"The angle between the wing and the oncoming air. More angle = more lift, until the critical angle, where the wing stalls."},
  {t:"Apron",say:"AY-prun",d:"The paved area where aircraft park, load, and refuel — often called the ramp."},
  {t:"ATC",say:"ay-tee-SEE",d:"Air Traffic Control: the ground-based system that sequences and separates aircraft from gate to gate."},
  {t:"Bypass ratio",say:"—",d:"In a turbofan, how much air flows around the engine core versus through it. Higher bypass = quieter and more efficient."},
  {t:"Ceiling (service)",say:"—",d:"The maximum altitude at which an aircraft can still climb at a useful rate."},
  {t:"Drag",say:"—",d:"Air resistance opposing motion. Parasite drag comes from shape and speed; induced drag is the cost of making lift."},
  {t:"ETOPS",say:"ee-TOPS",d:"Rules allowing twin-engine aircraft to fly routes far from diversion airports, based on proven engine reliability."},
  {t:"Flaps",say:"—",d:"Surfaces extending from the wing's trailing edge to add lift (and drag) for slow flight, takeoff, and landing."},
  {t:"Fly-by-wire",say:"—",d:"Flight controls where pilot inputs go to computers, which move the surfaces — enabling protections against unsafe commands."},
  {t:"Fuselage",say:"FYOO-suh-lahzh",d:"The aircraft's main body, holding crew, passengers, and cargo."},
  {t:"Go-around",say:"—",d:"A routine aborted landing: climb away, circle, try again. A normal safety maneuver, not an emergency."},
  {t:"Heading",say:"—",d:"The compass direction the aircraft's nose points, in degrees (000–359)."},
  {t:"IATA code",say:"eye-AH-tah",d:"The 3-letter airport code on tickets and bag tags (JFK, DXB, DEL)."},
  {t:"ICAO code",say:"eye-KAY-oh",d:"The 4-letter airport code used in flight operations (KJFK, OMDB, VIDP). First letters indicate the world region."},
  {t:"ILS",say:"eye-el-ESS",d:"Instrument Landing System: radio beams that guide aircraft down to the runway in poor visibility."},
  {t:"Knot",say:"not",d:"One nautical mile per hour (1.852 km/h) — aviation's standard speed unit."},
  {t:"Lift",say:"—",d:"The upward force made by wings deflecting air downward. Balances weight in level flight."},
  {t:"Mach number",say:"mahk",d:"Speed as a fraction of the speed of sound. Mach 2 = twice the speed of sound."},
  {t:"MTOW",say:"em-tee-oh-DUB-ul-yoo",d:"Maximum Takeoff Weight — the heaviest an aircraft is certified to be at the start of its takeoff roll."},
  {t:"Pitch, roll, yaw",say:"—",d:"The three axes of motion: nose up/down (pitch), wing tilt (roll), nose left/right (yaw)."},
  {t:"Rudder",say:"—",d:"The hinged surface on the vertical tail controlling yaw."},
  {t:"Runway designation",say:"—",d:"Runway numbers are magnetic headings divided by ten: heading 274° → Runway 27. Opposite ends differ by 18."},
  {t:"Stall",say:"stawl",d:"Loss of lift when the angle of attack exceeds the critical angle and airflow separates from the wing. Recovered by lowering the nose."},
  {t:"Supercruise",say:"—",d:"Sustained supersonic flight without afterburner — a signature capability of the F-22."},
  {t:"Thrust",say:"—",d:"The forward force from engines, balancing drag."},
  {t:"Turbofan",say:"TUR-boh-fan",d:"The modern jet engine: a large fan pushes most air around a hot core. Powers virtually all airliners."},
  {t:"V1",say:"vee-won",d:"Takeoff decision speed: below V1 you can stop; at or above V1 you fly, even after a failure."},
  {t:"Winglet",say:"WING-let",d:"An upturned wingtip that blocks vortex spill, cutting induced drag and saving fuel."},
  {t:"Yoke",say:"yohk",d:"The control column/wheel in many aircraft. Airbus uses sidesticks instead."}
];

